    throw new Error('Verifier recherche lot : exactement un item attendu de ' + (nom === null ? 'l\'entrée' : nom));
  }
  return items[0].json;
}

const liste = unItem("Chercher lot source");
if (!Array.isArray(liste.files) || liste.nextPageToken || liste.incompleteSearch) throw new Error('recherche du lot source inexploitable ou incomplète');
if (liste.files.length !== 1 || typeof liste.files[0].id !== 'string') throw new Error(liste.files.length + ' fichier(s) pour du lot source : exactement un attendu');
return [{ json: { fichier_id: liste.files[0].id } }];

// FONDA — pré-conditions §21.5 : référentiel, moteur, réservation au journal, lot source complet ; candidat existant et decisions/ PROUVÉ vide.
// GÉNÉRÉ par n8n/fonda-relecture-page/construire-relecture.js : ne pas éditer dans
// l'interface (le harnais compare ce code, octet pour octet, à celui du dépôt).

function unItem(nom) {
  const items = nom === null ? $input.all() : $(nom).all();
